window.chapter_socio_religious_reforms = {
  "title": "Socio Religious Reforms",
  "questions": [
    {"q": "Which of the following was NOT among the social evils prevalent in Indian society that led to the start of reformist movements?", "opts": ["Untouchability", "Purdah system", "Universal adult franchise", "Polygamy"], "ans": 2, "exp": "Universal adult franchise means voting rights for all adults, not a harmful social custom. Reformers were responding to practices such as untouchability, child marriage and restrictions on widows, which denied dignity and opportunity to particular groups."},
    {"q": "The position of women in Indian society deteriorated mainly due to polygamy and the prohibition of which practice?", "opts": ["Widow remarriage", "Female education", "Inter-caste marriage", "Temple entry"], "ans": 0, "exp": "Prohibiting widow remarriage could leave a woman socially isolated and dependent after her husband's death. Reformers challenged this restriction because it denied widows the chance to rebuild family life, especially when they had been married very young."},
    {"q": "In which year was the Act passed to abolish the Sati System in India?", "opts": ["1829", "1856", "1891", "1817"], "ans": 0, "exp": "The prohibition dates to 1829, when Bentinck's government outlawed sati in the Bengal Presidency. Campaigns against burning widows on their husbands' funeral pyres helped create pressure for a legal ban rather than leaving the matter to custom."},
    {"q": "The Act of 1829 abolishing the Sati System was passed largely due to the efforts of which reformer?", "opts": ["Raja Ram Mohan Roy", "Ishwar Chandra Vidyasagar", "Jyotiba Phule", "M.G. Ranade"], "ans": 0, "exp": "Raja Ram Mohan Roy campaigned against sati through petitions, public argument and discussion of religious texts. He challenged claims that the practice was an unavoidable religious duty, helping support the case for the government's prohibition in 1829."},
    {"q": "Who was the Governor-General of India when the Sati System was abolished in 1829?", "opts": ["Lord William Bentinck", "Lord Dalhousie", "Lord Canning", "Lord Curzon"], "ans": 0, "exp": "Lord William Bentinck issued the 1829 regulation prohibiting sati in Bengal. Roy was an important campaigner, while Bentinck held the governmental authority to turn opposition to the practice into a legally enforceable prohibition."},
    {"q": "In which year was the Widow Remarriage Act passed in India?", "opts": ["1856", "1829", "1891", "1929"], "ans": 0, "exp": "The Hindu Widows' Remarriage Act was passed in 1856. It removed legal obstacles to remarriage, but legislation alone could not remove the social stigma that continued to discourage widows and their families from accepting it."},
    {"q": "The Widow Remarriage Act of 1856 was passed largely due to the efforts of which reformer?", "opts": ["Ishwar Chandra Vidyasagar", "Raja Ram Mohan Roy", "Behramji M. Malabari", "Vishnu Shastri Pandit"], "ans": 0, "exp": "Ishwar Chandra Vidyasagar argued for widow remarriage using Hindu texts as well as appeals to humane treatment. This challenged opponents on their own religious grounds and helped build support for the 1856 legislation."},
    {"q": "Ishwar Chandra Vidyasagar, who worked for the Widow Remarriage Act, was Principal of which institution?", "opts": ["Sanskrit College", "Hindu College", "Elphinstone College", "Presidency College"], "ans": 0, "exp": "Vidyasagar was principal of Sanskrit College in Calcutta. His knowledge of Sanskrit and religious literature strengthened his ability to challenge orthodox arguments against widow remarriage rather than relying only on an appeal to Western ideas."},
    {"q": "The draft of the Widow Remarriage Act was prepared during the tenure of which Governor-General?", "opts": ["Lord Dalhousie", "Lord William Bentinck", "Lord Canning", "Lord Curzon"], "ans": 0, "exp": "The bill was introduced during Dalhousie's tenure, before its final enactment under Canning in 1856. The distinction is between preparing and introducing a proposed law and completing the legislative process that made it operative."},
    {"q": "The Widow Remarriage Act was finally enacted in 1856 under which Governor-General?", "opts": ["Lord Canning", "Lord Dalhousie", "Lord William Bentinck", "Lord Ripon"], "ans": 0, "exp": "Lord Canning was governor-general when the Act became law in 1856. Dalhousie's administration had begun the legislative process, so the two names refer to different stages of the same reform rather than separate widow-remarriage laws."},
    {"q": "Besides supporting widow remarriage, Ishwar Chandra Vidyasagar was also strongly against which social practice?", "opts": ["Child marriage", "Sati", "Untouchability", "Polygamy"], "ans": 0, "exp": "Vidyasagar opposed child marriage because it deprived girls of education and exposed them to early marital responsibilities and widowhood. His support for remarriage addressed one consequence of a system that could leave girls widowed while still very young."},
    {"q": "The Vidhava Vivaha Uttejaka Mandali (an association promoting widow remarriage) was formed by whom?", "opts": ["Vishnu Shastri Pandit", "M.G. Ranade", "Karsandas Mulji", "Jyotiba Phule"], "ans": 0, "exp": "Vishnu Shastri Pandit helped organise support for widow remarriage through the Vidhava Vivaha Uttejaka Mandali. Such associations were needed because legal permission did not protect families from social hostility or automatically persuade communities to accept remarriage."},
    {"q": "The Widow Remarriage Association was formed by which social reformer?", "opts": ["M.G. Ranade", "Vishnu Shastri Pandit", "Gopal Krishna Gokhale", "B.M. Malabari"], "ans": 0, "exp": "M.G. Ranade is associated with the Widow Remarriage Association. Organised advocacy sought to reduce opposition and make reform socially practicable, since widows still faced community pressure even after remarriage had received legal recognition."},
    {"q": "'Satyaprakash', a Gujarati weekly aimed at social reform, was founded by which social reformer and journalist?", "opts": ["Karsandas Mulji", "Vishnu Shastri Pandit", "Balshastri Jambhekar", "Gopal Hari Deshmukh"], "ans": 0, "exp": "Karsandas Mulji founded Satyaprakash to challenge social and religious abuses through Gujarati journalism. Publishing in a regional language allowed arguments about reform to reach readers beyond the smaller English-educated public."},
    {"q": "What was the intention behind the founding of the Gujarati weekly 'Satyaprakash' by Karsandas Mulji?", "opts": ["Social reform", "Political independence", "Promoting English education", "Trade union organisation"], "ans": 0, "exp": "Satyaprakash was intended to promote social reform. Its criticism brought practices defended by custom or religious authority into public debate, where readers could examine them instead of treating established leaders as beyond question."},
    {"q": "In which year was the Age of Consent Act passed in India?", "opts": ["1891", "1856", "1929", "1917"], "ans": 0, "exp": "The Age of Consent Act was passed in 1891. It raised the age below which sexual intercourse with a girl was an offence, including within marriage; this was distinct from setting a general minimum legal marriage age."},
    {"q": "The Age of Consent Act of 1891 was passed with the efforts of which social reformer?", "opts": ["Behramji M. Malabari", "Ishwar Chandra Vidyasagar", "Raja Ram Mohan Roy", "Gopal Krishna Gokhale"], "ans": 0, "exp": "Behramji Malabari campaigned against the harm caused by early marriage and pressed for protection of young girls. His advocacy contributed to the debate behind the 1891 Act, which changed the age of consent rather than directly prohibiting all marriages below twelve."},
    {"q": "As per the Age of Consent Act of 1891, marriage of girls below what age was not allowed?", "opts": ["12 years", "14 years", "18 years", "10 years"], "ans": 0, "exp": "Twelve is the intended figure, but the question misstates the law. The 1891 Act raised the age of consent from ten to twelve; it did not make twelve a general minimum marriage age. Consent and marriage-age restrictions are different legal provisions."},
    {"q": "In which year was the Sarda Act passed?", "opts": ["1929", "1891", "1856", "1917"], "ans": 0, "exp": "The Sarda Act was passed in 1929. It sought to restrain child marriage through minimum-age thresholds and penalties, moving beyond the earlier consent law to address the practice of arranging marriages while children were still very young."},
    {"q": "The Sarda Act of 1929 is also known by which other name?", "opts": ["Child Marriage Restraint Act", "Age of Consent Act", "Widow Remarriage Act", "Hindu Marriage Act"], "ans": 0, "exp": "Its official name was the Child Marriage Restraint Act. The name describes its purpose: to discourage underage marriages through legal penalties. Sarda refers to Harbilas Sarda, the legislator associated with the measure."},
    {"q": "As per the Sarda Act of 1929, what was the minimum age of marriage fixed for girls?", "opts": ["14 years", "12 years", "18 years", "16 years"], "ans": 0, "exp": "The original 1929 Act set fourteen as the minimum marriage age for girls. This is the historical threshold asked about, not a statement of present law. The reform aimed to delay marriage and reduce the harms associated with marrying children."},
    {"q": "As per the Sarda Act of 1929, what was the minimum age of marriage fixed for boys?", "opts": ["18 years", "14 years", "21 years", "16 years"], "ans": 0, "exp": "The original Act set eighteen as the minimum marriage age for boys. Applying thresholds to both sexes made child marriage a matter of public regulation rather than leaving its timing entirely to families and established social custom."},
    {"q": "In which year did Thomas Babington Macaulay present Macaulay's Minute?", "opts": ["1835", "1854", "1813", "1882"], "ans": 0, "exp": "Macaulay presented his Minute in 1835. It supported spending educational funds on English instruction and European learning, taking a side in the debate over whether government support should prioritise classical scholarship or Western subjects."},
    {"q": "Macaulay's Minute of 1835 was presented with which main objective?", "opts": ["To promote English education in India", "To promote vernacular education in India", "To establish universities in India", "To abolish the Downward Filtration Theory"], "ans": 0, "exp": "The objective was to promote English-medium education and European knowledge. Macaulay wanted a class of educated Indians who could mediate between colonial rulers and the population, so the policy also served administrative needs."},
    {"q": "Which theory was propounded by Thomas Babington Macaulay regarding the spread of English education in India?", "opts": ["Downward Filtration Theory", "Wood's Despatch Theory", "Trickle-Up Theory", "Vernacular Primacy Theory"], "ans": 0, "exp": "Downward Filtration Theory expected learning to pass from a small educated upper section of society to the wider population. It justified concentrating resources on that group rather than beginning with government-funded schooling for everyone."},
    {"q": "Under the Downward Filtration Theory, English-medium education was intended primarily for whom?", "opts": ["Only rich Indians", "All Indians equally", "Only women", "Only government officials"], "ans": 0, "exp": "The answer 'only rich Indians' is too narrow. Filtration policy targeted an educated upper section expected to pass knowledge downwards. The central idea was selective investment at the top, not a formal rule that wealth alone determined eligibility."},
    {"q": "Who among the following, the Governor-General of India in 1835, is regarded as the 'Father of English Education in India'?", "opts": ["Lord William Bentinck", "Lord Dalhousie", "Lord Canning", "Lord Curzon"], "ans": 0, "exp": "Lord William Bentinck's government adopted the 1835 policy supporting English education after Macaulay's Minute. Bentinck supplied the official decision; Macaulay supplied the influential argument. The title in the question reflects Bentinck's role in implementing that policy."},
    {"q": "In which year was Wood's Despatch issued?", "opts": ["1854", "1835", "1891", "1813"], "ans": 0, "exp": "Wood's Despatch was issued in 1854. It proposed a more organised educational system, linking primary schools with higher institutions and administrative support, rather than depending only on knowledge filtering down from a small elite."},
    {"q": "Wood's Despatch of 1854 rejected which earlier theory of education?", "opts": ["Downward Filtration Theory", "Vernacular Primacy Theory", "Chaturvarna Theory", "Anglo-Vernacular Theory"], "ans": 0, "exp": "It moved away from relying solely on downward filtration by advocating a broader educational structure. Primary schooling, teacher training and links between levels of education mattered because an educated minority alone could not ensure learning reached the population."},
    {"q": "Wood's Despatch of 1854 is also known as the:", "opts": ["Magna Carta of Indian Education", "Bible of Indian Education", "Charter of Indian Reforms", "Minute on Indian Education"], "ans": 0, "exp": "The nickname refers to the Despatch's comprehensive proposals for organising education. It addressed different levels of schooling, administration and support for institutions, making it a landmark policy document rather than a recommendation about one subject alone."},
    {"q": "According to Wood's Despatch, in which medium should primary level education be imparted?", "opts": ["Vernacular", "English", "Anglo-Vernacular", "Persian"], "ans": 0, "exp": "Vernacular means the local or regional language used by the community. Teaching primary pupils through a familiar language could make basic learning accessible without first requiring them to master English."},
    {"q": "According to Wood's Despatch, in which medium should secondary level education be imparted?", "opts": ["Anglo-Vernacular", "Vernacular", "English", "Persian"], "ans": 0, "exp": "Anglo-vernacular schooling combined English with an Indian language. At the secondary stage, this could connect education begun in the local language with the English learning increasingly required for higher study and colonial employment."},
    {"q": "According to Wood's Despatch, in which medium should higher level education be imparted?", "opts": ["English", "Vernacular", "Anglo-Vernacular", "Persian"], "ans": 0, "exp": "English was recommended for higher education. It provided access to the European literature and scientific works prioritised by colonial policy, while the proposed use of regional languages at lower levels served a different educational stage."},
    {"q": "In which year was the Bharat Stree Mahamandal founded?", "opts": ["1910", "1904", "1917", "1925"], "ans": 0, "exp": "Bharat Stree Mahamandal was founded in 1910. It sought to connect efforts for women's education across communities, addressing restrictions that kept many women away from formal learning and organised public activity."},
    {"q": "Who founded the Bharat Stree Mahamandal in 1910?", "opts": ["Sarla Devi Chaudharani", "Ramabai Ranade", "Annie Besant", "Lady Meherbai Tata"], "ans": 0, "exp": "Sarla Devi Chaudharani founded the organisation to advance women's education and collective organisation. Building an association helped extend the work beyond individual households and bring women from different places into a shared reform effort."},
    {"q": "In which year was the Ladies Social Conference founded?", "opts": ["1904", "1910", "1925", "1927"], "ans": 0, "exp": "The Ladies Social Conference dates to 1904. Such gatherings gave women a forum to discuss their educational and social concerns publicly, at a time when many were expected to remain confined to domestic roles."},
    {"q": "Who founded the Ladies Social Conference in 1904?", "opts": ["Ramabai Ranade", "Sarla Devi Chaudharani", "Margaret Cousins", "Pandita Ramabai Saraswati"], "ans": 0, "exp": "Ramabai Ranade is associated with the Ladies Social Conference. Her work promoted women's education and public participation, encouraging women to develop the confidence and organisational experience needed to speak about conditions affecting their lives."},
    {"q": "In which year was the Women's Indian Association founded?", "opts": ["1917", "1910", "1925", "1881"], "ans": 0, "exp": "The Women's Indian Association was founded in 1917. It connected women's education and welfare with demands for political rights, including the vote, treating women as participants in public decision-making rather than only beneficiaries of reform."},
    {"q": "Annie Besant and Margaret Cousins were among the founders of which organisation established in 1917?", "opts": ["Women's Indian Association", "Bharat Stree Mahamandal", "All India Women's Conference", "National Council of Women in India"], "ans": 0, "exp": "The organisation was the Women's Indian Association. Besant, Cousins and their colleagues linked education and social improvement with political participation, since women needed a voice in the institutions making decisions about their lives."},
    {"q": "In which year was the National Council of Women in India founded?", "opts": ["1925", "1917", "1927", "1881"], "ans": 0, "exp": "The National Council of Women in India was formed in 1925. It connected women's organisations and gave them a platform for presenting concerns about education, welfare and women's legal and social position."},
    {"q": "Who founded the National Council of Women in India in 1925?", "opts": ["Lady Meherbai Tata", "Sarla Devi Chaudharani", "Margaret Cousins", "Ramabai Ranade"], "ans": 0, "exp": "Lady Meherbai Tata was an important founder and organiser associated with the Council. Its national network helped bring local women's welfare efforts into wider discussions, making collective representation possible beyond any one city or association."},
    {"q": "In which year was the All India Women's Conference founded?", "opts": ["1927", "1917", "1925", "1910"], "ans": 0, "exp": "The All India Women's Conference began in 1927, initially focusing on women's education. Bringing participants together allowed them to compare educational needs and press for improvements that isolated local efforts might struggle to obtain."},
    {"q": "Who founded the All India Women's Conference in 1927?", "opts": ["Margaret Cousins", "Lady Meherbai Tata", "Sarla Devi Chaudharani", "Pandita Ramabai Saraswati"], "ans": 0, "exp": "Margaret Cousins took the initiative in organising the conference. Its early educational focus reflected the belief that women's opportunities depended on access to learning, before its work expanded into a broader programme of rights and reform."},
    {"q": "In which year was the Arya Mahila Samaj founded?", "opts": ["1881", "1910", "1904", "1925"], "ans": 0, "exp": "The question gives 1881, but the Arya Mahila Samaj is generally dated to 1882. Pandita Ramabai established it to promote women's education and challenge practices such as child marriage. The discrepancy concerns the date, not the organisation's identity."},
    {"q": "Who founded the Arya Mahila Samaj in 1881?", "opts": ["Pandita Ramabai Saraswati", "Ramabai Ranade", "Sarla Devi Chaudharani", "Lady Meherbai Tata"], "ans": 0, "exp": "Pandita Ramabai established the Arya Mahila Samaj to support women's education and social improvement. Her Sanskrit scholarship gave her unusual authority to question customs restricting women, while the association offered a practical platform for reform."},
    {"q": "The first university for Indian women, SNDT, was founded in which year?", "opts": ["1916", "1910", "1927", "1925"], "ans": 0, "exp": "Karve founded the institution in 1916, initially as the Indian Women's University. Creating a university specifically for women opened a path beyond basic schooling when access to higher education remained severely restricted."},
    {"q": "Who founded SNDT, the first university for Indian women?", "opts": ["Dr Dhondo Keshav Karve", "B.R. Ambedkar", "Gopal Krishna Gokhale", "Jyotiba Phule"], "ans": 0, "exp": "Dhondo Keshav Karve founded the university as part of his wider work for women's education. An institution offering advanced study could give women qualifications and opportunities that charitable assistance or elementary literacy alone could not provide."},
    {"q": "In which year was the Bahishkrit Hitakarini Sabha established?", "opts": ["1924", "1927", "1925", "1917"], "ans": 0, "exp": "The Bahishkrit Hitakarini Sabha was established in 1924. Its work addressed the education and welfare of people subjected to untouchability, creating an organisation through which excluded communities could pursue their interests collectively."},
    {"q": "The Bahishkrit Hitakarini Sabha (1924) was established by whom?", "opts": ["B.R. Ambedkar", "E.V. Ramaswamy Naicker", "Narayana Guru", "Jyotiba Phule"], "ans": 0, "exp": "B.R. Ambedkar founded the Sabha to promote education and social advancement among oppressed castes. He saw organised action as necessary because exclusion affected access to institutions and rights, not just relations between individual people."},
    {"q": "The Bahishkrit Hitakarini Sabha was established by B.R. Ambedkar at which place?", "opts": ["Bombay", "Nagpur", "Mahad", "Poona"], "ans": 0, "exp": "The Sabha was established in Bombay, now Mumbai. The city provided a base for organising educational and welfare activity, connecting Ambedkar's public work with people and institutions able to support a sustained campaign against caste exclusion."},
    {"q": "In which year was the Self Respect Movement started?", "opts": ["1925", "1924", "1927", "1917"], "ans": 0, "exp": "Periyar launched the Self Respect Movement in 1925. It urged people to reject the inferior status assigned by caste and to question social authority, linking dignity with changes in marriage, gender relations and everyday conduct."},
    {"q": "The Self Respect Movement of 1925 was started by whom?", "opts": ["E.V. Ramaswamy Naicker", "B.R. Ambedkar", "Narayana Guru", "Jyotiba Phule"], "ans": 0, "exp": "E.V. Ramaswamy, known as Periyar, founded the movement. He argued that inherited caste privilege and ritual authority kept people subordinate, so achieving self respect required questioning the customs that made inequality appear natural or sacred."},
    {"q": "The Self Respect Movement started by E.V. Ramaswamy Naicker began in which region?", "opts": ["Tamil Nadu", "Kerala", "Maharashtra", "Punjab"], "ans": 0, "exp": "The movement developed in Tamil Nadu, then within the Madras Presidency. Its attack on caste hierarchy and priestly control addressed local structures of social power and influenced marriage practices, public debate and later regional politics."},
    {"q": "A movement similar to the Self Respect Movement, against caste-based exploitation, was started by Narayana Guru in which region?", "opts": ["Kerala", "Tamil Nadu", "Maharashtra", "Bengal"], "ans": 0, "exp": "Narayana Guru worked in Kerala, where caste restrictions limited access to worship, education and shared public spaces. His message of equality challenged the belief that a person's birth should determine spiritual worth or social opportunities."},
    {"q": "A movement similar to the Self Respect Movement, against caste-based exploitation, was started by Jyotiba Phule in which region?", "opts": ["Maharashtra", "Kerala", "Tamil Nadu", "Punjab"], "ans": 0, "exp": "Jyotiba Phule worked in Maharashtra. He challenged caste privilege through education and the Satyashodhak Samaj, arguing that oppressed communities needed knowledge and organisation to question the authority keeping them subordinate."},
    {"q": "In which year was the Mahad Satyagraha led?", "opts": ["1927", "1924", "1925", "1930"], "ans": 0, "exp": "The Mahad Satyagraha took place in 1927. Its immediate demand was access to the public Chavdar tank, turning the right to draw water into a practical test of whether people treated as untouchable enjoyed equal civic rights."},
    {"q": "The Mahad Satyagraha of 1927 was led by whom?", "opts": ["B.R. Ambedkar", "E.V. Ramaswamy Naicker", "Narayana Guru", "M.C. Rajah"], "ans": 0, "exp": "Ambedkar led the Mahad campaign for equal access to public water. Drawing from the tank openly challenged a social prohibition, demonstrating that a formally public resource was still being denied to people because of caste."},
    {"q": "The Mahad Satyagraha of 1927, led by B.R. Ambedkar, was directed against what?", "opts": ["An ancient text that upheld caste laws", "A temple that barred Dalit entry", "A tax imposed on Dalits", "A ban on inter-caste marriage"], "ans": 0, "exp": "The central demand at Mahad was access to the public Chavdar tank. The answer refers to the later burning of the Manusmriti, which rejected caste authority. These were connected actions, but the water-rights struggle and the symbolic burning were distinct."},
    {"q": "In which year was the first Hindu College at Benaras founded?", "opts": ["1791", "1817", "1814", "1825"], "ans": 0, "exp": "The Benaras Sanskrit College was founded in 1791. It supported traditional Sanskrit learning, reflecting the early colonial policy of working through established scholarship rather than the later preference for English education associated with Macaulay."},
    {"q": "The first Hindu College at Benaras (1791) was founded by whom?", "opts": ["Jonathan Duncan", "David Hare", "Raja Ram Mohan Roy", "William Bentinck"], "ans": 0, "exp": "Jonathan Duncan established the college to encourage Sanskrit scholarship. Colonial administrators also hoped that access to learned interpreters of Hindu texts would assist their understanding and administration of the society they governed."},
    {"q": "Raja Ram Mohan Roy is popularly known as the:", "opts": ["Father of Indian Renaissance", "Father of Indian Unrest", "Father of the Indian Constitution", "Father of English Education in India"], "ans": 0, "exp": "Roy is called the Father of the Indian Renaissance because he linked religious rethinking with social reform, education and public debate. The title recognises intellectual renewal and challenges to harmful customs, rather than political rule or military achievement."},
    {"q": "Raja Ram Mohan Roy was given the title of 'Raja' by whom?", "opts": ["Akbar II", "Bahadur Shah Zafar", "Shah Alam II", "Lord William Bentinck"], "ans": 0, "exp": "Akbar II gave Roy the title Raja in connection with his mission to Britain on the emperor's behalf. The title should not be mistaken for evidence that Roy governed a kingdom; it was an honour associated with his representative role."},
    {"q": "Raja Ram Mohan Roy founded the Atmiya Sabha in which city?", "opts": ["Calcutta", "Bombay", "Madras", "Lahore"], "ans": 0, "exp": "Roy founded the Atmiya Sabha in Calcutta. Meeting there allowed him and like-minded thinkers to discuss religious beliefs and social practices, building a forum for questioning orthodoxy before the creation of the Brahmo Sabha."},
    {"q": "In which year did Raja Ram Mohan Roy found the Atmiya Sabha?", "opts": ["1814", "1817", "1825", "1828"], "ans": 0, "exp": "The listed answer is 1814, but the Atmiya Sabha is commonly dated to 1815. It provided a discussion circle for Roy's religious and social ideas, preparing the ground for his more organised Brahmo initiative in 1828."},
    {"q": "The Atmiya Sabha, founded by Raja Ram Mohan Roy, was the forerunner of which organisation?", "opts": ["Brahmo Samaj", "Arya Samaj", "Prarthana Samaj", "Veda Samaj"], "ans": 0, "exp": "The Atmiya Sabha preceded the Brahmo Samaj. Its discussions about belief in one God and criticism of accepted practices helped develop the ideas that later received a more formal institutional expression through Roy's Brahmo Sabha."},
    {"q": "Raja Ram Mohan Roy founded the Hindu College in Calcutta with the help of whom?", "opts": ["David Hare", "Jonathan Duncan", "Debendranath Tagore", "Henry Vivian Derozio"], "ans": 0, "exp": "David Hare is the intended collaborator. He promoted modern education in Calcutta and helped establish Hindu College. The founding involved several supporters, so the question simplifies a collective educational initiative into a partnership between two people."},
    {"q": "In which year was the Hindu College in Calcutta founded with the help of David Hare?", "opts": ["1817", "1814", "1825", "1828"], "ans": 0, "exp": "Hindu College in Calcutta was founded in 1817. It became an important centre of English and Western learning, creating the educational setting in which Derozio's students later questioned established religious and social conventions."},
    {"q": "In which year did Raja Ram Mohan Roy found the Vedanta College?", "opts": ["1825", "1817", "1814", "1828"], "ans": 0, "exp": "Roy established Vedanta College around 1825 to combine Vedanta study with modern learning. He wanted Indians to engage with scientific knowledge while examining their own philosophical traditions, rather than treating traditional scholarship and new subjects as mutually exclusive."},
    {"q": "In which year did Raja Ram Mohan Roy found the Brahmo Sabha, which later became the Brahmo Samaj?", "opts": ["1828", "1825", "1817", "1814"], "ans": 0, "exp": "Roy founded the Brahmo Sabha in 1828. It created an organised setting for worship of one God without idol worship, translating ideas previously discussed in reform circles into a continuing religious institution."},
    {"q": "Which of the following practices did Raja Ram Mohan Roy advocate against?", "opts": ["Sati, idol worship, polytheism and child marriage", "English education for Indians", "Establishment of newspapers", "Foundation of colleges"], "ans": 0, "exp": "Roy opposed these practices because he challenged both harmful social customs and religious claims he regarded as inconsistent with reason or monotheism. His campaign against sati directly connected this religious criticism with the protection of women's lives."},
    {"q": "'Tuhfat-ul-Muwahhidin' (Gift to Monotheists), a work advocating monotheism, was written by whom?", "opts": ["Raja Ram Mohan Roy", "Ishwar Chandra Vidyasagar", "Swami Dayanand Saraswati", "Sir Syed Ahmad Khan"], "ans": 0, "exp": "Roy wrote Tuhfat-ul-Muwahhidin, or Gift to Monotheists. Monotheism means belief in one God; the work reflects his effort to examine religious belief rationally rather than accept every inherited practice as necessary to faith."},
    {"q": "'The Precepts of Jesus' was written by which social reformer?", "opts": ["Raja Ram Mohan Roy", "Keshab Chandra Sen", "Debendranath Tagore", "Ishwar Chandra Vidyasagar"], "ans": 0, "exp": "Roy wrote The Precepts of Jesus, focusing on ethical teachings. His interest in their moral message illustrates his willingness to study ideas across religious boundaries without accepting every doctrine associated with a particular religious institution."},
    {"q": "'Sambad Kaumudi', a periodical brought out by Raja Ram Mohan Roy, was published in which language?", "opts": ["Bengali", "Persian", "Sanskrit", "Urdu"], "ans": 0, "exp": "Sambad Kaumudi was published in Bengali. Using Bengali brought reform arguments, including opposition to sati, to a local reading public instead of limiting discussion to people who understood English or scholarly languages."},
    {"q": "'Mirat-ul-Akbar', a periodical brought out by Raja Ram Mohan Roy, was published in which language?", "opts": ["Persian", "Bengali", "Sanskrit", "Urdu"], "ans": 0, "exp": "Mirat-ul-Akbar was published in Persian, a language with an established educated readership. It gave Roy another channel for discussing public affairs and reform, distinct from the Bengali audience reached by Sambad Kaumudi."},
    {"q": "In which year did Devendranath Tagore start the Tattvabodhini Sabha?", "opts": ["1839", "1828", "1866", "1878"], "ans": 0, "exp": "Debendranath Tagore founded the Tattvabodhini Sabha in 1839. It encouraged study and discussion of religious ideas, helping renew the intellectual and organisational life of the Brahmo movement after Roy's death."},
    {"q": "The organ of the Tattvabodhini Sabha, the Tattvabodhini Patrika, was published in which language?", "opts": ["Bengali", "Persian", "Sanskrit", "Hindi"], "ans": 0, "exp": "The Tattvabodhini Patrika was published in Bengali. Its language helped carry religious and social discussion to Bengali readers, extending the Sabha's influence beyond people able to attend meetings in person."},
    {"q": "In which year did Devendranath Tagore invite Keshab Chandra Sen to join the Brahmo Samaj?", "opts": ["1838", "1839", "1866", "1878"], "ans": 0, "exp": "The date 1838 is incorrect: it was Keshab Chandra Sen's birth year. He joined the Brahmo Samaj in 1857 and later became a major reforming leader. His differences with Debendranath contributed to the division of 1866."},
    {"q": "Due to philosophical differences, the Brahmo Samaj split into two groups in which year?", "opts": ["1866", "1838", "1878", "1875"], "ans": 0, "exp": "The split occurred in 1866. Disagreements over religious authority and the extent of social reform separated Keshab Chandra Sen's followers from Debendranath Tagore's group, producing two organisations within the broader Brahmo tradition."},
    {"q": "After the 1866 split, the Brahmo Samaj of India was led by whom?", "opts": ["Keshab Chandra Sen", "Debendranath Tagore", "Ananda Mohan Bose", "Radhakanta Deb"], "ans": 0, "exp": "Keshab Chandra Sen led the Brahmo Samaj of India. His more activist approach to spreading the movement and pursuing social reform brought him into conflict with the older leadership, contributing to the separation in 1866."},
    {"q": "After the 1866 split, the Adi Brahmo Samaj was led by whom?", "opts": ["Debendranath Tagore", "Keshab Chandra Sen", "Ananda Mohan Bose", "Radhakanta Deb"], "ans": 0, "exp": "Debendranath Tagore's group retained the name Adi Brahmo Samaj. Adi means original, signalling its continuity with the earlier organisation after Sen's followers formed a separate body in 1866."},
    {"q": "The Sadharan Brahmo Samaj, formed after a further split in the Adi Brahmo Samaj, was founded in which year?", "opts": ["1878", "1866", "1839", "1838"], "ans": 0, "exp": "The Sadharan Brahmo Samaj was formed in 1878. It emerged from opposition within Sen's Brahmo Samaj of India, not from the Adi branch as the question states. His daughter's marriage intensified criticism over consistency and leadership."},
    {"q": "Who founded the Sadharan Brahmo Samaj in 1878?", "opts": ["Ananda Mohan Bose", "Debendranath Tagore", "Keshab Chandra Sen", "Radhakanta Deb"], "ans": 0, "exp": "Ananda Mohan Bose was among the founders, together with other dissenting Brahmos. The new organisation opposed excessive personal authority and the departure from reform principles associated with Sen's daughter's marriage."},
    {"q": "In which year was the Veda Samaj formed in Madras?", "opts": ["1864", "1873", "1875", "1867"], "ans": 0, "exp": "The Veda Samaj began in Madras in 1864, showing the spread of Brahmo-inspired religious reform beyond Bengal. It encouraged belief in one God and criticism of social divisions, adapting those concerns to a southern setting."},
    {"q": "The Veda Samaj was formed in Madras in 1864 by Keshab Chandra Sen along with whom?", "opts": ["K. Sridharalu Naidu", "K.G. Ranade", "Dadoba Pandurang", "Atmaram Pandurang"], "ans": 0, "exp": "K. Sridharalu Naidu is the answer intended here and an important later organiser of the movement. The question compresses different stages: the Veda Samaj began after Sen's 1864 visit, while Naidu's reorganisation belongs to its subsequent development."},
    {"q": "The Veda Samaj is also known by which other name?", "opts": ["Brahmo Samaj of South India", "Arya Samaj of South India", "Prarthana Samaj of South India", "Dharma Sabha of South India"], "ans": 0, "exp": "It is associated with the name Brahmo Samaj of South India because its religious reform followed the Brahmo tradition. The name identifies a regional expression of the movement, rather than another organisation founded directly in Bengal."},
    {"q": "In which year was the Dharma Sabha, a revivalist movement, started?", "opts": ["1830", "1849", "1867", "1873"], "ans": 0, "exp": "The Dharma Sabha began in 1830. It defended orthodox religious and social practices against reforms such as the prohibition of sati, illustrating that reform campaigns faced organised opposition as well as support."},
    {"q": "The Dharma Sabha (1830), which opposed the reforms of the Brahmo Samaj, was started by whom?", "opts": ["Radhakanta Deb", "Debendranath Tagore", "Henry Vivian Derozio", "Keshab Chandra Sen"], "ans": 0, "exp": "Radhakanta Deb led the Dharma Sabha. He defended established Hindu customs and resisted reforms he regarded as interference with religious tradition, placing the organisation on the opposing side of debates associated with Roy's reform work."},
    {"q": "The Young Bengal Movement (late 1820s and early 1830s) was started by whom?", "opts": ["Henry Vivian Derozio", "Radhakanta Deb", "Debendranath Tagore", "Ananda Mohan Bose"], "ans": 0, "exp": "Henry Vivian Derozio inspired the Young Bengal Movement through his teaching. He encouraged students to examine beliefs through reason and evidence, making intellectual independence and criticism of orthodoxy central to the group."},
    {"q": "Henry Vivian Derozio, who started the Young Bengal Movement, was a teacher at which institution?", "opts": ["Hindu College", "Sanskrit College", "Elphinstone College", "Presidency College"], "ans": 0, "exp": "Derozio taught at Hindu College in Calcutta. His close interaction with students provided the setting for Young Bengal, whose members took classroom questioning into debates about religion, social customs and freedom of thought."},
    {"q": "The Paramhans Mandali was formed in 1849, although SSC considers its formation year as which year?", "opts": ["1840", "1830", "1856", "1867"], "ans": 0, "exp": "The Paramhans Mandali is generally dated to 1849. The claim that SSC instead requires 1840 has no examination reference supplied here. Its relevant historical role was challenging caste restrictions, not establishing an alternative examination-specific chronology."},
    {"q": "The Paramhans Mandali, formed in Maharashtra, was founded by Dadoba Pandurang along with whom?", "opts": ["Durgaram Manchharam", "Atmaram Pandurang", "M.G. Ranade", "R.G. Bhandarkar"], "ans": 0, "exp": "Durgaram Manchharam is named alongside Dadoba Pandurang. The Mandali questioned caste restrictions, including barriers to sharing meals, using a small reform circle because public defiance could bring exclusion from the wider community."},
    {"q": "In which year was the Prarthana Samaj formed?", "opts": ["1867", "1849", "1873", "1875"], "ans": 0, "exp": "The Prarthana Samaj was founded in 1867. It combined worship of one God with social reform, supporting changes in caste relations and women's position rather than treating religious practice as separate from everyday inequality."},
    {"q": "The Prarthana Samaj (1867) was formed by whom in Maharashtra?", "opts": ["Atmaram Pandurang", "Dadoba Pandurang", "Jyotiba Phule", "M.G. Ranade"], "ans": 0, "exp": "Atmaram Pandurang founded the Prarthana Samaj in Bombay. It offered an organised forum for religious and social reform, drawing inspiration from the Brahmo movement while developing within Maharashtra's own reform environment."},
    {"q": "In which year did M.G. Ranade join the Prarthana Samaj?", "opts": ["1870", "1867", "1873", "1875"], "ans": 0, "exp": "Ranade joined in 1870. His association strengthened the movement's practical reform work, including support for women's education and widow remarriage, linking religious discussion with efforts to change social conditions."},
    {"q": "Besides M.G. Ranade, which other notable figure was a member of the Prarthana Samaj?", "opts": ["R.G. Bhandarkar", "Sir Syed Ahmad Khan", "Radhakanta Deb", "Dadoba Pandurang"], "ans": 0, "exp": "R.G. Bhandarkar was a prominent member. His scholarship helped the movement engage with Indian religious traditions while questioning practices that reformers considered harmful, allowing criticism of custom without simply dismissing the entire tradition."},
    {"q": "In which year was the Deoband Movement started?", "opts": ["1866", "1873", "1875", "1887"], "ans": 0, "exp": "The Deoband movement dates to the establishment of its seminary in 1866. Its founders sought to preserve and renew Islamic scholarship under colonial rule by training religious scholars through an independent educational institution."},
    {"q": "The Deoband Movement (1866) was started by Muhammad Qasim Nanautavi along with whom?", "opts": ["Rashid Ahmad Gangohi", "Sir Syed Ahmad Khan", "Sayyid Ahmad Barelvi", "Haji Shariatullah"], "ans": 0, "exp": "Rashid Ahmad Gangohi was a major scholar associated with the initiative alongside Qasim Nanautavi. Their emphasis was religious learning and moral renewal, giving Deoband a different educational approach from Aligarh's emphasis on modern Western subjects."},
    {"q": "The Deoband Movement (1866) was launched in which district?", "opts": ["Saharanpur, Uttar Pradesh", "Amritsar, Punjab", "Aligarh, Uttar Pradesh", "Lahore, Punjab"], "ans": 0, "exp": "Deoband is in Saharanpur district, Uttar Pradesh. The town gave its name to the seminary and the wider school of thought, so the movement's geographical name refers to its institutional origin rather than a founder's surname."},
    {"q": "In which year was the Singh Sabha Movement started?", "opts": ["1873", "1866", "1875", "1887"], "ans": 0, "exp": "The first Singh Sabha was established in 1873. It responded to concerns about Sikh religious identity through education and renewed attention to Sikh teachings, in a setting where missionary activity and religious debate were increasing."},
    {"q": "The Singh Sabha Movement (1873) was started in which city?", "opts": ["Amritsar", "Lahore", "Saharanpur", "Bombay"], "ans": 0, "exp": "The first Singh Sabha was founded at Amritsar, an important Sikh religious centre. Organising there gave the renewal effort a strong community setting from which to promote education and clarify Sikh beliefs and practices."},
    {"q": "The Singh Sabha Movement primarily aimed to do what?", "opts": ["Revive Sikh faith by bringing back converts", "Promote English education among Sikhs", "Abolish the practice of Sati", "Establish a Sikh university"], "ans": 0, "exp": "Strengthening Sikh identity was the wider aim; bringing converts back was one part of it. The movement also promoted education and Sikh teachings, so its purpose should not be reduced to reconversion alone."},
    {"q": "In which year was the Satyashodhak Samaj formed?", "opts": ["1873", "1866", "1848", "1875"], "ans": 0, "exp": "Phule founded the Satyashodhak Samaj in 1873. Its name means Society of Truth Seekers, expressing the idea that people should question claims used to justify caste privilege rather than accept them because of birth or tradition."},
    {"q": "The Satyashodhak Samaj (1873), formed against caste discrimination in Maharashtra, was founded by whom?", "opts": ["Jyotiba Phule", "Dadoba Pandurang", "Atmaram Pandurang", "M.G. Ranade"], "ans": 0, "exp": "Jyotiba Phule founded it to organise resistance to caste domination. He argued that oppressed communities needed education and independent religious and social practices so that their lives were not controlled by those claiming hereditary superiority."},
    {"q": "Jyotiba Phule, founder of the Satyashodhak Samaj, belonged to which community?", "opts": ["Mali (Gardener) community", "Brahmin community", "Kayastha community", "Rajput community"], "ans": 0, "exp": "Phule came from the Mali, or gardener, community. His experience of caste hierarchy informed his criticism of inherited privilege, but his reform programme addressed the oppression of wider communities rather than only the interests of his own caste."},
    {"q": "In which year did Jyotiba Phule, along with his wife, start the first school for girls in Pune?", "opts": ["1848", "1873", "1866", "1856"], "ans": 0, "exp": "Jyotirao and Savitribai Phule opened their pioneering girls' school at Pune in 1848. Girls' education challenged both gender restrictions and caste barriers, making the school a practical form of resistance to the exclusion they criticised."},
    {"q": "Savitri Phule, who helped start the first girls' school in Pune, is remembered as:", "opts": ["The first female teacher of India", "The first female doctor of India", "The first female graduate of India", "The first female journalist of India"], "ans": 0, "exp": "Savitribai Phule is honoured as a pioneering woman teacher. Her teaching made girls' education possible despite strong social hostility; the contribution to remember is her direct educational work and challenge to gender and caste exclusion."},
    {"q": "'Gulamgiri', a book written by Jyotiba Phule, was written in which language?", "opts": ["Marathi", "Gujarati", "Bengali", "Hindi"], "ans": 0, "exp": "Gulamgiri was written in Marathi. Phule used it to criticise caste domination and expose the ideas that kept oppressed communities subordinate. Writing in Marathi made that challenge accessible beyond readers of English or Sanskrit."},
    {"q": "Which of the following is a book written by Jyotiba Phule?", "opts": ["Sarasjanik Satyadharma", "Satyarth Prakash", "Tuhfat-ul-Muwahhidin", "Raja Yoga"], "ans": 0, "exp": "The title intended is Sarvajanik Satya Dharma, though the option misspells it. Phule's work proposed an ethical religious outlook rejecting caste privilege, consistent with his effort to make dignity and moral worth independent of inherited social rank."},
    {"q": "In which year was the Arya Samaj founded?", "opts": ["1875", "1873", "1887", "1866"], "ans": 0, "exp": "The Arya Samaj was founded in 1875. Dayanand sought reform through a return to what he regarded as the original authority of the Vedas, challenging later customs rather than defending every existing Hindu practice."},
    {"q": "The Arya Samaj (1875) was founded by whom?", "opts": ["Swami Dayanand Saraswati", "Swami Vivekananda", "Sir Syed Ahmad Khan", "Shiv Narayan Agnihotri"], "ans": 0, "exp": "Swami Dayanand Saraswati founded the Arya Samaj. He used Vedic authority to criticise idol worship and inherited social restrictions, believing that religious renewal required removing practices he considered later distortions."},
    {"q": "What was the original name of Swami Dayanand Saraswati, founder of the Arya Samaj?", "opts": ["Mool Shankar", "Narendranath Dutta", "Gadadhar Chattopadhyay", "Lokhitwadi"], "ans": 0, "exp": "His original name was Mool Shankar. Dayanand Saraswati was the name associated with his life as a renunciant and reformer, under which he founded the Arya Samaj and developed his call to return to the Vedas."},
    {"q": "The first unit of the Arya Samaj was formed in Bombay and was later shifted to which city?", "opts": ["Lahore", "Amritsar", "Delhi", "Madras"], "ans": 0, "exp": "Lahore became a major Arya Samaj centre after its Bombay foundation. Describing this simply as shifting the first unit is misleading: the movement expanded, and Punjab became especially important for its organisation and educational institutions."},
    {"q": "Which of the following slogans is associated with the Arya Samaj?", "opts": ["'Go Back to Vedas' and 'Pride for Indians'", "'One Jathi, One Mathom, One Daivam'", "'Dar-ul-Islam'", "'National Youth Day'"], "ans": 0, "exp": "The central slogan was 'Go Back to the Vedas'. Dayanand believed that religious and social improvement required recovering Vedic principles rather than accepting practices merely because they had become customary."},
    {"q": "Swami Dayanand Saraswati considered the Vedas as infallible but was critical of which texts?", "opts": ["Puranas", "Upanishads", "Vedanta", "Smritis"], "ans": 0, "exp": "Dayanand criticised the Puranas while treating the Vedas as authoritative. This distinction let him reject beliefs and practices he viewed as later additions without abandoning his claim to be restoring an authentic religious foundation."},
    {"q": "Swami Dayanand Saraswati, founder of the Arya Samaj, believed in which of the following concepts?", "opts": ["Karma and Reincarnation", "Trinity and Original Sin", "Predestination", "Nirvana alone, rejecting rebirth"], "ans": 0, "exp": "Karma links actions with their consequences, while reincarnation concerns rebirth. Dayanand accepted these ideas within his religious outlook, even as he opposed practices such as idol worship that he did not regard as properly Vedic."},
    {"q": "Swami Dayanand Saraswati subscribed to the Chaturvarna system on what basis?", "opts": ["Work, not birth", "Birth, not work", "Wealth", "Region"], "ans": 0, "exp": "He argued that varna should depend on qualities and work rather than birth. This challenged hereditary claims to status, although it should not be confused with rejecting every form of social classification altogether."},
    {"q": "Swami Dayanand Saraswati, founder of the Arya Samaj, was strongly against which practice?", "opts": ["Idol worship", "Widow remarriage", "English education", "Temple entry for Dalits"], "ans": 0, "exp": "Dayanand rejected idol worship because he understood God as formless and believed worship should follow Vedic principles. His opposition was part of a religious reform programme, not a rejection of belief in God."},
    {"q": "'Satyarth Prakash' was written by whom?", "opts": ["Swami Dayanand Saraswati", "Swami Vivekananda", "Raja Ram Mohan Roy", "Sir Syed Ahmad Khan"], "ans": 0, "exp": "Dayanand wrote Satyarth Prakash to explain his understanding of true religion and criticise beliefs he considered mistaken. It set out the Vedic reasoning behind reforms associated with the Arya Samaj."},
    {"q": "In which year was the Dayanand Anglo-Vedic (DAV) College established in Lahore in memory of Swami Dayanand Saraswati?", "opts": ["1886", "1875", "1893", "1920"], "ans": 0, "exp": "The DAV institution at Lahore began in 1886 in Dayanand's memory. Its educational approach sought to combine modern learning with Vedic inspiration, making institution-building a practical continuation of his reform programme."},
    {"q": "The Dayanand Anglo-Vedic (DAV) College in Lahore was established in memory of Swami Dayanand Saraswati with the key role of whom?", "opts": ["Hansraj", "Ananda Mohan Bose", "K. Sridharalu Naidu", "Durgaram Manchharam"], "ans": 0, "exp": "Lala Hansraj played a central role in establishing and running the Lahore DAV institution. His work turned admiration for Dayanand into sustained educational activity, rather than limiting the memorial to religious meetings or a monument."},
    {"q": "In 1893, the Arya Samaj members in Punjab split into two groups over the questions of vegetarianism and modern education. What was the group that retained abstinence from meat known as?", "opts": ["Mahatma group", "Cultured Party", "Sadharan group", "Gurukul Party"], "ans": 0, "exp": "The Mahatma group stressed stricter observance, including abstinence from meat. The dispute also concerned education, showing that Arya Samaj members disagreed about how Dayanand's principles should guide daily conduct and the institutions they built."},
    {"q": "In 1893, the Arya Samaj members in Punjab split into two groups over vegetarianism and modern education. What was the other group (favouring modern education) known as?", "opts": ["Cultured Party", "Mahatma group", "Sadharan group", "Gurukul Party"], "ans": 0, "exp": "The Cultured Party favoured the college-based approach associated with modern education. Its disagreement with the stricter group concerned how best to combine religious commitments with contemporary learning, not whether Dayanand deserved respect."},
    {"q": "In which year was the Aligarh Movement started?", "opts": ["1875", "1866", "1873", "1887"], "ans": 0, "exp": "The year 1875 marks Sir Syed's school at Aligarh, a major institutional milestone. The movement developed over time: the institution became MAO College in 1877 and later a university, so it did not begin as a fully formed university project on one date."},
    {"q": "The Aligarh Movement (1875) was started by whom?", "opts": ["Sir Syed Ahmad Khan", "Sayyid Ahmad Barelvi", "Haji Shariatullah", "Muhammad Qasim Nanautavi"], "ans": 0, "exp": "Sir Syed Ahmad Khan promoted modern education among Muslims to improve access to knowledge and employment under colonial rule. His work centred on institutions and public discussion, addressing educational disadvantage rather than relying only on religious instruction."},
    {"q": "Sir Syed Ahmad Khan established the Mohammadan Anglo Oriental College in 1875; in which year did it become the Aligarh Muslim University?", "opts": ["1920", "1888", "1886", "1893"], "ans": 0, "exp": "Aligarh Muslim University was established in 1920. The question compresses its earlier stages: a school began in 1875 and MAO College followed in 1877. University status was a later development, not the institution's original form."},
    {"q": "Sir Syed Ahmad Khan founded the Indian Patriotic Association in which year?", "opts": ["1888", "1875", "1920", "1893"], "ans": 0, "exp": "Sir Syed helped establish the United Indian Patriotic Association in 1888. It opposed the Congress's claim to represent all Indians and reflected his concerns about political representation; this was a political initiative distinct from his educational work."},
    {"q": "'Tahdhib-ul-Akhlaq', a magazine aimed at the improvement of manners and morals, was published by whom?", "opts": ["Sir Syed Ahmad Khan", "Swami Dayanand Saraswati", "Raja Ram Mohan Roy", "Shiv Narayan Agnihotri"], "ans": 0, "exp": "Sir Syed published Tahdhib-ul-Akhlaq to encourage moral, social and intellectual reform among Muslims. A periodical could challenge accepted habits and explain modern ideas to readers beyond those able to attend his educational institutions."},
    {"q": "In which year was the Dev Samaj founded?", "opts": ["1887", "1875", "1866", "1873"], "ans": 0, "exp": "Shiv Narayan Agnihotri founded the Dev Samaj in 1887. Its emphasis on ethical conduct made personal behaviour and social improvement central concerns, distinguishing it from movements whose main organising principle was a return to Vedic authority."},
    {"q": "The Dev Samaj (1887) was founded by whom at Lahore?", "opts": ["Shiv Narayan Agnihotri", "Swami Dayanand Saraswati", "Sir Syed Ahmad Khan", "Hansraj"], "ans": 0, "exp": "Shiv Narayan Agnihotri founded the Dev Samaj at Lahore. The organisation stressed moral development and responsible conduct, making reform of everyday behaviour a central part of its religious programme."},
    {"q": "The Shuddhi Movement, initiated by the Arya Samaj, aimed to do what?", "opts": ["Reconvert people who had converted to Islam and Christianity back to Hinduism", "Convert people from Hinduism to other religions", "Abolish idol worship in temples", "Promote English education among converts"], "ans": 0, "exp": "Shuddhi sought to bring people back into the Hindu community through a formal process of reconversion. The campaign addressed religious membership and identity, making it different from Arya Samaj activities focused on schooling or criticism of social customs."},
    {"q": "Swami Vivekananda started which mission?", "opts": ["Ramkrishna Mission", "Arya Samaj", "Brahmo Samaj", "Prarthana Samaj"], "ans": 0, "exp": "Vivekananda founded the Ramakrishna Mission to organise practical service alongside spiritual work. It translated the ideal of serving people into institutions and activities, rather than limiting religion to personal worship or philosophical discussion."},
    {"q": "What was the original name of Swami Vivekananda?", "opts": ["Narendranath Dutta", "Mool Shankar", "Gadadhar Chattopadhyay", "Lokhitwadi"], "ans": 0, "exp": "Vivekananda's original name was Narendranath Dutta. His monastic name belongs to his later life as Ramakrishna's disciple and a religious teacher, so the question distinguishes his family identity from the name under which he became widely known."},
    {"q": "Swami Vivekananda's birthday, 12 January 1863, is celebrated as:", "opts": ["National Youth Day", "National Education Day", "National Reform Day", "National Unity Day"], "ans": 0, "exp": "His birthday, 12 January, is observed as National Youth Day. The commemoration connects young people with his emphasis on confidence, strength, education and responsibility towards others, rather than marking the foundation date of the Mission."},
    {"q": "On what date did Swami Vivekananda die?", "opts": ["4 July 1902", "12 January 1863", "4 July 1893", "1 January 1902"], "ans": 0, "exp": "Vivekananda died on 4 July 1902 at Belur Math. By then he had founded the Mission, giving his ideas about spirituality and organised service an institutional form that could continue beyond his lifetime."},
    {"q": "Which of the following books was written by Swami Vivekananda?", "opts": ["Raja Yoga", "Satyarth Prakash", "Gulamgiri", "Tuhfat-ul-Muwahhidin"], "ans": 0, "exp": "Vivekananda wrote Raja Yoga, explaining a disciplined approach to the mind and spiritual practice. The title is connected with meditation and concentration, rather than a political theory about kingship despite the everyday meaning of raja."},
    {"q": "In which year did Swami Vivekananda deliver his famous speech at a conference in Chicago, USA?", "opts": ["1893", "1902", "1886", "1863"], "ans": 0, "exp": "He addressed the World's Parliament of Religions at Chicago in 1893. The gathering gave him an international platform to present Hindu thought and argue for religious tolerance, helping establish his reputation beyond India."},
    {"q": "Swami Vivekananda advocated for balance between which two aspects of life?", "opts": ["Materialism and Spiritualism", "Capitalism and Socialism", "Tradition and Modernity", "East and West"], "ans": 0, "exp": "He linked spiritual development with practical improvement in people's lives. Material needs such as food and education could not simply be ignored, while prosperity without ethical purpose was also insufficient; this explains the pairing of material and spiritual concerns."},
    {"q": "The Swami Vivekananda Rock Memorial is located in which state?", "opts": ["Tamil Nadu", "Kerala", "West Bengal", "Maharashtra"], "ans": 0, "exp": "The memorial is at Kanyakumari in Tamil Nadu, on a rock associated with Vivekananda's meditation. The location connects the monument with a particular episode in his travels, rather than with the Mission's headquarters at Belur."},
    {"q": "In which year was the Ramkrishna Mission started?", "opts": ["1897", "1886", "1902", "1875"], "ans": 0, "exp": "Vivekananda founded the Mission in 1897. Organising monks and lay supporters together made it possible to carry out continuing educational, medical and relief work as an expression of spiritual responsibility."},
    {"q": "The Ramkrishna Mission (1897) was started by Swami Vivekananda in the memory of whom?", "opts": ["Ramkrishna Paramahamsa", "Swami Dayanand Saraswati", "Raja Ram Mohan Roy", "Debendranath Tagore"], "ans": 0, "exp": "The Mission honours Ramakrishna Paramahamsa, Vivekananda's teacher. Vivekananda gave the teachings an organised service programme, so Ramakrishna supplied the spiritual inspiration while his disciple created the institution."},
    {"q": "Ramkrishna Paramahamsa, Guru of Swami Vivekananda, was a priest of which temple in Calcutta?", "opts": ["Kali Mandir", "Kalaram Temple", "Belur Math", "Jagannath Temple"], "ans": 0, "exp": "Ramakrishna served at the Kali temple at Dakshineswar near Calcutta. His devotion to Kali was central to his spiritual life, and this temple setting became an important meeting place for the disciples who gathered around him."},
    {"q": "What was the original name of Ramkrishna Paramahamsa?", "opts": ["Gadadhar Chattopadhyay", "Narendranath Dutta", "Mool Shankar", "Lokhitwadi"], "ans": 0, "exp": "His original name was Gadadhar Chattopadhyay. Ramakrishna was the name under which he became known as a spiritual teacher; the question distinguishes that later religious identity from his birth name."},
    {"q": "What is the headquarters of the Ramkrishna Mission?", "opts": ["Belur Math, Howrah (West Bengal)", "Adyar, Madras", "Lahore", "Nagpur"], "ans": 0, "exp": "Belur Math is in Howrah, West Bengal, on the bank of the Ganga. It serves as the central institutional base of the Ramakrishna order and Mission, rather than the Dakshineswar temple where Ramakrishna had served."},
    {"q": "According to Swami Vivekananda and the Ramkrishna Mission's philosophy, service to whom is considered service to God?", "opts": ["Mankind", "Only Brahmins", "Only monks", "Only the wealthy"], "ans": 0, "exp": "Serving mankind is understood as serving God because the philosophy recognises the divine in human beings. Helping someone through education, treatment or relief therefore becomes a spiritual act, not merely charity separate from religious practice."},
    {"q": "Which two newspapers were started by Balshastri Jambhekar?", "opts": ["Darpan and Digdarshan", "Prabhakar and Hitechhu", "Sudharak and Kesari", "Darpan and Sudharak"], "ans": 0, "exp": "Jambhekar started Darpan and Digdarshan. Darpan was a newspaper, while Digdarshan was a periodical associated with spreading knowledge; calling both newspapers overlooks this difference in format and purpose."},
    {"q": "Balshastri Jambhekar is remembered as the:", "opts": ["Father of Marathi Journalism", "Father of Indian Renaissance", "Father of English Education in India", "Father of Marathi Theatre"], "ans": 0, "exp": "He is called the Father of Marathi Journalism because of his pioneering role in developing the Marathi press, especially Darpan. Journalism created a public channel for knowledge and criticism beyond face-to-face meetings or formal classrooms."},
    {"q": "What was the pen name of Gopal Hari Deshmukh?", "opts": ["Lokhitwadi", "Sudharak", "Periyar", "Vidyasagar"], "ans": 0, "exp": "Lokhitwadi was Deshmukh's pen name, meaning one concerned with the public good. It suited his criticism of harmful customs and inherited privilege, presenting reform as a question of society's welfare rather than private religious observance alone."},
    {"q": "Which weekly newspapers were started by Gopal Hari Deshmukh (Lokhitwadi)?", "opts": ["Prabhakar and Hitechhu", "Darpan and Digdarshan", "Sudharak", "Kesari and Maratha"], "ans": 0, "exp": "The answer conflates writing for a publication with founding it. Deshmukh's Shatapatre appeared in Prabhakar, which was founded by Bhau Mahajan. His important connection is as a reformist writer; Prabhakar should not simply be credited to him as founder."},
    {"q": "Which weekly newspaper was started by Gopal Ganesh Agarkar?", "opts": ["Sudharak", "Prabhakar", "Darpan", "Digdarshan"], "ans": 0, "exp": "Agarkar started Sudharak, whose name means reformer. It provided a platform for criticism of orthodoxy and arguments for social change, allowing him to pursue reform through public reasoning and journalism."},
    {"q": "In which year was the Servants of India Society founded?", "opts": ["1905", "1908", "1911", "1897"], "ans": 0, "exp": "The Servants of India Society was founded in 1905. It sought trained, committed workers for sustained public service, making social and educational improvement a continuing vocation rather than an occasional charitable activity."},
    {"q": "Who founded the Servants of India Society in 1905?", "opts": ["Gopal Krishna Gokhale", "Narayana Malhar Joshi", "B.M. Malabari", "Gopal Ganesh Agarkar"], "ans": 0, "exp": "Gopal Krishna Gokhale founded the Society. He believed that national progress required people willing to dedicate their lives to public work, so training and disciplined service were as important as speeches or political resolutions."},
    {"q": "Gopal Krishna Gokhale, founder of the Servants of India Society, was the political Guru of which leaders?", "opts": ["Gandhi and Jinnah", "Nehru and Patel", "Tilak and Lajpat Rai", "Ambedkar and Periyar"], "ans": 0, "exp": "Gandhi regarded Gokhale as his political mentor, while Jinnah also admired his constitutional approach. The association reflects Gokhale's influence through persuasion and public service; the term guru does not imply identical political views among all three."},
    {"q": "The Servants of India Society (1905) was founded with which purpose?", "opts": ["To promote education and social service in India", "To reconvert people to Hinduism", "To promote English education alone", "To abolish caste-based temple entry restrictions"], "ans": 0, "exp": "Its purpose was education and social service carried out by dedicated workers. Improving public life required people who could work consistently within communities, so the Society emphasised preparation, commitment and service above personal advancement."},
    {"q": "In which year was Seva Sadan founded?", "opts": ["1908", "1905", "1911", "1917"], "ans": 0, "exp": "The Bombay Seva Sadan began in 1908. It sought practical help for women through education, training and support, addressing the difficulty of becoming independent when social restrictions had limited both schooling and employment opportunities."},
    {"q": "Seva Sadan (1908) was founded by whom?", "opts": ["B.M. Malabari", "Gopal Krishna Gokhale", "Narayana Malhar Joshi", "Gopal Ganesh Agarkar"], "ans": 0, "exp": "B.M. Malabari helped found the Bombay Seva Sadan with colleagues, including Dayaram Gidumal. The institution connected advocacy for women with practical assistance, rather than leaving reform at the level of petitions and public debate."},
    {"q": "Seva Sadan, founded by B.M. Malabari, worked against child marriage and in favour of what?", "opts": ["Widow remarriage", "Sati abolition", "English education", "Temple entry"], "ans": 0, "exp": "Widow remarriage is the intended answer. Opposition to it could leave women isolated and dependent; Seva Sadan's wider work also provided education and training, recognising that women needed practical opportunities as well as changes in marriage customs."},
    {"q": "In which year was the Social Service League founded?", "opts": ["1911", "1908", "1905", "1917"], "ans": 0, "exp": "The Social Service League was established in 1911. It addressed urban welfare through organised activity, responding to problems of education, living conditions and support among people affected by the growth of industrial cities."},
    {"q": "The Social Service League (1911) was founded by whom, at Bombay?", "opts": ["Narayana Malhar Joshi", "Gopal Krishna Gokhale", "B.M. Malabari", "Gopal Ganesh Agarkar"], "ans": 0, "exp": "Narayana Malhar Joshi founded the League in Bombay. The city's industrial population made workers' welfare an important concern, linking his social-service work with his later prominence in organised labour."},
    {"q": "Narayana Malhar Joshi, founder of the Social Service League, also started which organisation in 1920?", "opts": ["All India Trade Union Congress", "All India Depressed Classes Association", "Servants of India Society", "Self Respect Movement"], "ans": 0, "exp": "Joshi helped found the All India Trade Union Congress in 1920 and served as its first general secretary. Bringing unions together gave workers a national platform; he was an important organiser, not its sole founder."},
    {"q": "The Fara'izi movement, a boxed note alongside the Wahabi Movement, was started by whom?", "opts": ["Haji Shariatullah", "Sayyid Ahmad Barelvi", "Muhammad Qasim Nanautavi", "Sir Syed Ahmad Khan"], "ans": 0, "exp": "Haji Shariatullah founded the Faraizi movement in Bengal. Faraiz refers to obligatory religious duties, so the movement called Muslims back to what it regarded as essential Islamic observance rather than inherited practices without that authority."},
    {"q": "The Wahabi Movement, a Muslim revivalist movement, was started by whom?", "opts": ["Sayyid Ahmad Barelvi", "Haji Shariatullah", "Muhammad Qasim Nanautavi", "Sir Syed Ahmad Khan"], "ans": 0, "exp": "Sayyid Ahmad Barelvi led the Indian revivalist movement described here. He sought religious renewal and a community governed by Islamic principles; this Indian movement should not be treated as identical in every respect to the Arabian movement sharing the Wahabi label."},
    {"q": "The Wahabi Movement, started by Sayyid Ahmad Barelvi, was popularly known as:", "opts": ["Tariqa-e-Muhammadiya", "Tahdhib-ul-Akhlaq", "Shuddhi Movement", "Dar-ul-Islam Movement"], "ans": 0, "exp": "Tariqa-e-Muhammadiya means the path or way of Muhammad. The name expresses the movement's call to follow the Prophet's example and reform practices its supporters believed had departed from authentic Islamic teaching."},
    {"q": "Sayyid Ahmad Barelvi and his followers worked to transform India from Dar-ul-Harb into what?", "opts": ["Dar-ul-Islam", "Dar-ul-Harb", "Dar-ul-Uloom", "Dar-ul-Aman"], "ans": 0, "exp": "Dar-ul-Islam meant a territory governed in accordance with Islamic principles. The aim was therefore political as well as religious: changing individual conduct alone would not fulfil a programme that also concerned the authority governing the community."},
    {"q": "The Satnami Movement was started in the 1820s in which region?", "opts": ["Chhattisgarh", "Kerala", "Tamil Nadu", "Punjab"], "ans": 0, "exp": "The movement developed in Chhattisgarh in the early nineteenth century. Guru Ghasidas's message challenged the low status imposed on marginalised communities, giving followers a shared religious identity through which to assert dignity."},
    {"q": "The Satnami Movement was started by whom?", "opts": ["Guru Ghasidas", "Guru Ravidas", "Shree Narayana Guru", "Narayana Guru"], "ans": 0, "exp": "Guru Ghasidas led this Satnami movement. His teachings emphasised truth and human equality, challenging the claim that inherited caste position made some people intrinsically less worthy than others."},
    {"q": "Guru Ghasidas, who started the Satnami Movement, worked to improve the social status of which occupational group?", "opts": ["Leatherworkers", "Weavers", "Potters", "Ironsmiths"], "ans": 0, "exp": "Leatherworkers were among the communities whose dignity the movement asserted. Their occupation was stigmatised through caste, so improving their position meant challenging the social judgement attached to their work, not merely changing how the work was performed."},
    {"q": "In which year was the Theosophical Society started?", "opts": ["1875", "1882", "1887", "1897"], "ans": 0, "exp": "The Theosophical Society was founded in New York in 1875. It encouraged comparative study of religion and spiritual inquiry, seeking shared understanding across traditions rather than creating a society restricted to one national or religious community."},
    {"q": "The Theosophical Society (1875) was started in New York (USA) by whom?", "opts": ["HP Blavatsky and HS Olcott", "Annie Besant and Margaret Cousins", "Sarla Devi Chaudharani and Ramabai Ranade", "M.G. Ranade and Raghunath Rao"], "ans": 0, "exp": "Helena Petrovna Blavatsky and Henry Steel Olcott were the principal founders named here. Their interest in spiritual inquiry and comparative religion helped create an organisation that later developed important links with Indian religious and educational life."},
    {"q": "In which year was the headquarters of the Theosophical Society shifted from New York to Adyar, Madras?", "opts": ["1882", "1875", "1887", "1893"], "ans": 0, "exp": "The headquarters moved to Adyar in 1882. Establishing a permanent base near Madras placed the Society closer to the Indian traditions it studied and gave its international activities a continuing institutional centre."},
    {"q": "Which leader later took membership of the Theosophical Society and became closely associated with it in India?", "opts": ["Annie Besant", "Margaret Cousins", "Sarla Devi Chaudharani", "Pandita Ramabai Saraswati"], "ans": 0, "exp": "Annie Besant joined the Society and became a prominent leader in its Indian work. Her involvement connected spiritual inquiry with educational activity, while her later political campaigns extended beyond the Society's religious and philosophical concerns."},
    {"q": "The Theosophical Society helped spread which belief system in India?", "opts": ["Hindu belief system", "Christianity", "Islam", "Buddhism"], "ans": 0, "exp": "The Society encouraged renewed appreciation of Hindu thought, which explains the answer. Its scope was broader, however: comparative religion and universal brotherhood included interest in Buddhism and other traditions, rather than exclusive promotion of a single faith."},
    {"q": "In which year was the Indian National Social Conference founded?", "opts": ["1887", "1897", "1905", "1875"], "ans": 0, "exp": "The Indian National Social Conference began in 1887. It created a forum for social questions alongside nationalist political activity, since debates about India's progress also involved marriage customs, caste barriers and women's education."},
    {"q": "The Indian National Social Conference (1887) was founded by M.G. Ranade along with whom?", "opts": ["Raghunath Rao", "Gopal Krishna Gokhale", "B.M. Malabari", "R.G. Bhandarkar"], "ans": 0, "exp": "Raghunath Rao helped establish the Conference with M.G. Ranade. They wanted an organised setting for social reform, ensuring that constitutional and political demands did not crowd out discussion of inequality within Indian society."},
    {"q": "The Pledge Movement, started by the founders of the Indian National Social Conference, was directed against what?", "opts": ["Child marriage", "Idol worship", "Untouchability", "English education"], "ans": 0, "exp": "The pledge campaign opposed child marriage. Asking people to commit publicly not to arrange such marriages tried to change family behaviour directly, since discussion or legal reform alone could leave everyday decisions unchanged."},
    {"q": "The Shree Narayana Guru Dharam Paripalana (SNDP) Movement was started by whom?", "opts": ["Shree Narayana Guru", "E.V. Ramaswamy Naicker", "K.P. Kesava Menon", "T.K. Madhavan"], "ans": 0, "exp": "Narayana Guru inspired the movement; SNDP Yogam was organised in 1903 with important roles for Dr Palpu and Kumaran Asan. Its purpose was to turn the Guru's message of equality into sustained community organisation and advancement."},
    {"q": "The SNDP Movement, started by Shree Narayana Guru, worked for the upliftment of which community in Kerala?", "opts": ["Ezhavas", "Nairs", "Brahmins", "Satnamis"], "ans": 0, "exp": "The SNDP worked especially for the advancement of Ezhavas in Kerala. Exclusion from education, public opportunities and religious spaces required collective organisation, so reform involved practical access as well as a spiritual message of equality."},
    {"q": "Which slogan is associated with the SNDP Movement started by Shree Narayana Guru?", "opts": ["One Jathi, One Mathom, One Daivam", "Go Back to Vedas", "Dar-ul-Islam", "Service is service to God"], "ans": 0, "exp": "The slogan means 'One Caste, One Religion, One God for All'. It rejects the idea that birth creates separate levels of human worth, expressing Narayana Guru's message that dignity and spiritual value are shared."},
    {"q": "In which year was the Justice Movement started?", "opts": ["1917", "1925", "1927", "1905"], "ans": 0, "exp": "The question uses 1917, associated with the Justice newspaper and the movement's public development. The South Indian Liberal Federation, or Justice Party, was founded in 1916. These milestones should be distinguished rather than treated as a single foundation date."},
    {"q": "The Justice Movement (1917) was started by C.N. Mudaliyar, T.M. Nair, and which other leader?", "opts": ["P. Tyagaraja", "E.V. Ramaswamy Naicker", "K.P. Kesava Menon", "T.K. Madhavan"], "ans": 0, "exp": "P. Theagaraya Chetty is the leader intended by the spelling P. Tyagaraja. Alongside Natesa Mudaliar and T.M. Nair, he helped organise non-Brahmin political demands for fairer access to education, public employment and representation."},
    {"q": "The Self Respect Movement (1925), founded by E.V. Ramaswamy Naicker (Periyar) in Tamil Nadu, had which main objective?", "opts": ["Rejection of Brahminical dominance and rituals", "Promotion of English education", "Reconversion to Hinduism", "Temple entry for Dalits alone"], "ans": 0, "exp": "The movement opposed caste privilege and priestly control because these could make inequality seem religiously compulsory. Periyar encouraged rational questioning and self-respect marriages, seeking dignity in everyday life as well as changes in political representation."},
    {"q": "The Civil Disobedience Movement in Kerala was led by whom?", "opts": ["K. Kelappan", "T.K. Madhavan", "K.P. Kesava Menon", "Shree Narayana Guru"], "ans": 0, "exp": "K. Kelappan was a prominent leader of Civil Disobedience in Kerala, including the salt campaign at Payyanur. Breaking the salt law connected the national challenge to colonial authority with direct public participation in the region."},
    {"q": "'Amar Jiban', written by Rasundari Devi, holds which distinction?", "opts": ["1st known autobiography written by an Indian woman", "1st novel written by an Indian woman", "1st Indian women's magazine", "1st Indian women's newspaper"], "ans": 0, "exp": "Rasundari Devi's Amar Jiban is recognised as a pioneering autobiography by an Indian woman. Writing her own life was especially significant because she had learned to read despite restrictions on women's literacy, leaving a voice often absent from official records."},
    {"q": "The Temple Entry Movement, for the entry of Dalits into temples, was started by Dr B.R. Ambedkar in which year?", "opts": ["1927", "1924", "1930", "1917"], "ans": 0, "exp": "NCERT dates the beginning of Ambedkar's temple-entry movement to 1927. These campaigns exposed caste prejudice by asserting equal access to religious spaces. The Kalaram campaign at Nashik began later, in 1930, so its date should not replace the broader movement's starting year."},
    {"q": "In South India, the Temple Entry Movement was started in 1924 by whom?", "opts": ["T.K. Madhavan", "K.P. Kesava Menon", "K. Kelappan", "C.N. Mudaliyar"], "ans": 0, "exp": "T.K. Madhavan was a key organiser of the 1924 Vaikom struggle. Its immediate issue was caste-based exclusion from roads around the temple; road access should be distinguished from a general right to enter the temple itself."},
    {"q": "The Vaikom Satyagraha of 1924 was started by whom?", "opts": ["K.P. Kesava Menon", "T.K. Madhavan", "K. Kelappan", "Shree Narayana Guru"], "ans": 0, "exp": "K.P. Kesava Menon was an important Vaikom leader alongside Madhavan, Kelappan and others. Describing him as the sole founder oversimplifies a collective campaign that challenged restrictions preventing oppressed castes from using roads around the temple."},
    {"q": "'Stri Purush Tulana' was written by whom?", "opts": ["Tarabai Shinde", "Rasundari Devi", "Savitribai Phule", "Pandita Ramabai Saraswati"], "ans": 0, "exp": "Tarabai Shinde wrote Stri Purush Tulana, a comparison of women and men. She challenged the double standard that condemned women while excusing similar conduct by men, making unequal moral judgement itself the subject of criticism."},
    {"q": "In 1930, B.R. Ambedkar led a notable temple entry Satyagraha for the entry of Dalits at which temple in Nashik?", "opts": ["Kalaram Temple", "Jagannath Temple", "Kali Mandir", "Vaikom Temple"], "ans": 0, "exp": "The campaign concerned Kalaram Temple in Nashik. Ambedkar's supporters demanded equal access because exclusion from worship publicly reinforced caste inferiority; challenging that barrier was part of a wider struggle for dignity and civic equality."},
    {"q": "In which year was the All India Depressed Classes Association formed in Nagpur?", "opts": ["1926", "1930", "1924", "1917"], "ans": 0, "exp": "The association dates to 1926. It sought a collective political voice for communities then described as the Depressed Classes, linking social advancement with representation rather than relying entirely on reform by more privileged groups."},
    {"q": "The All India Depressed Classes Association (1926), formed in Nagpur, was led by whom?", "opts": ["M.C. Rajah", "B.R. Ambedkar", "T.K. Madhavan", "K.P. Kesava Menon"], "ans": 0, "exp": "M.C. Rajah led the association. His public work pressed for the rights and representation of oppressed castes, reflecting the growth of organisations through which those communities could put forward their own political demands."},
    {"q": "In which year was the All India Depressed Classes Congress formed?", "opts": ["1930", "1926", "1924", "1917"], "ans": 0, "exp": "The All India Depressed Classes Congress met at Nagpur in 1930. It brought representatives together to discuss the position of oppressed castes during major debates over India's constitutional future and political representation."},
    {"q": "The All India Depressed Classes Congress (1930) was led by whom?", "opts": ["Dr B.R. Ambedkar", "M.C. Rajah", "T.K. Madhavan", "E.V. Ramaswamy Naicker"], "ans": 0, "exp": "Ambedkar led the 1930 gathering. He argued that political arrangements needed safeguards for people excluded by caste, since a transfer of power alone would not automatically provide equal rights or protection from social domination."},
  ]
};
